232	\label{tab:mmct_cross}
233	\begin{tabular}{lc}
234	\toprule
235	Condition & Sig / 8 \\
236	\midrule
237	Baseline (Pythia-410M / Wiki)     & 5/8 \\
238	Architecture: GPT-2-medium / Wiki & \textbf{7/8} \\
239	Architecture: OPT-1.3B / Wiki     & 5/8 \\
